+__aicore__ inline void CalcSeqLenAndOffset(const ConstInfo<isInfer, hasRope>& constInfo,
+    int32_t bIdx, __gm__ int64_t* actualSeqQlenAddr, int64_t& actualSeqLen, int64_t& seqOffset)
+{
