+/*!
+ * \file vf_basic_block_128_common_sfa.h
+ * \brief shared __simd_callee__ helpers for 128-element aligned/unaligned SFA kernels
+ */
+#ifndef VF_BASIC_BLOCK_128_COMMON_SFA_H
+#define VF_BASIC_BLOCK_128_COMMON_SFA_H
+
